from fastapi.testclient import TestClient

def dep_a(security_scopes: SecurityScopes):
    print(f"dep_a called with scopes: {security_scopes.scopes}")
    return security_scopes.scopes

def dep_b(security_scopes: SecurityScopes, a_scopes = Depends(dep_a)):
    print(f"dep_b called with scopes: {security_scopes.scopes}")
    print(f"dep_b's a_scopes: {a_scopes}")
    return {"a_scopes": a_scopes, "b_scopes": security_scopes.scopes}

router = APIRouter(dependencies=[Security(dep_a, scopes=["scope_router"])])

@router.get("/test")
def read_test(res = Security(dep_b, scopes=["scope_route"])):
    return res

app = FastAPI()
app.include_router(router)

client = TestClient(app)

def test_propagation():
    response = client.get("/test")
    print(f"Response: {response.json()}")
    assert response.status_code == 200
    assert response.json()["b_scopes"] == ["scope_route"]
    assert response.json()["a_scopes"] == ["scope_route"]

if __name__ == "__main__":
    try:
        test_propagation()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"Error: {e}")
", "filepath": "_check.py"}

